import threading

class View:
    def __init__(self):
        self._lock = threading.Lock()
        self.rows = []
        self.notes = {}
        self.loading = False
        self.error = None
        self.seq = 0

    def begin(self, query) -> int:
        with self._lock:
            self.error = None
            self.seq += 1
            return self.seq

    def finish(self, request_id, rows):
        with self._lock:
            if request_id == self.seq:
                self.rows = rows
                self.loading = False
                return True
            else:
                return False
